import sys

def length_of_last_word_opt(s: str) -> int:
    i = len(s) - 1
    while i >= 0 and s[i] == ' ':
        i -= 1
    end = i
    while i >= 0 and s[i] != ' ':
        i -= 1
    return end - i

if __name__ == '__main__':
    s = sys.stdin.readline().rstrip('\n')
    print(length_of_last_word_opt(s))

import sys

def length_of_last_word_best(s: str) -> int:
    n = len(s)
    i, length = n - 1, 0
    while i >= 0:
        if s[i] == ' ':
            if length > 0:
                break
        else:
            length += 1
        i -= 1
    return length

if __name__ == '__main__':
    s = sys.stdin.readline().rstrip('\n')
    print(length_of_last_word_best(s))
